"""Explain shadow/origin, context selection and recursive runtime guards."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1713': ('공책 옆에 두 검사표를 둔다고 생각해요. 하나는 각 칸의 준비 상태, 다른 하나는 준비되지 않은 상태가 어디서 시작됐는지를 적어요.', 'shadow와 origin의 역할과 저장 단위를 구별합니다.', '4바이트 경계에 맞춘 데이터8칸 옆에 shadow8칸과 origin 두 묶음을 그리세요.', ['KMSAN은 아직 값을 제대로 준비하지 않은 메모리를 사용하는 실수를 찾는 도구예요. 실제 데이터 옆에 검사에 필요한 정보인 메타데이터를 관리해요. shadow와 origin은 이 검사 정보의 두 종류예요.', 'shadow는 데이터의 초기화 상태를 바이트 단위로 따라가요. 바이트는 메모리 크기를 세는 단위예요. 한 데이터 바이트에는 한 shadow 바이트가 대응하며 그 안의 비트로 준비되지 않은 부분을 나타낼 수 있어요. 데이터 값이0이라는 것과 준비되지 않았다는 상태는 같지 않아요.', 'origin은 준비되지 않은 상태의 원인을 추적하는 기록과 연결돼요. KMSAN_ORIGIN_SIZE는4이고 원인 정보는4바이트 단위와 연결돼요. handle은 긴 원인 기록 자체 대신 그 기록을 가리키는 식별자예요. 모든 데이터 바이트마다 서로 독립적인 origin을 하나씩 둔다고 생각하면 안 돼요.', '4바이트 경계에 맞춰 시작하는 데이터8바이트를 예로 들면 shadow는8바이트, origin은 두 단위로 그릴 수 있어요. 시작 주소가 경계에 맞지 않으면 걸치는 원인 단위 수가 달라질 수 있으므로 단순히 길이만4로 나누는 예를 모든 주소에 적용하지 마세요.', 'shadow_origin_ptr 구조체에는 void *shadow와 *origin이라는 두 주소가 있어요. 포인터는 어디에 있는지를 알려 주는 값이에요. 두 포인터는 실제 데이터 주소 대신 두 검사 정보의 위치를 함께 전달하는 역할이에요. 선언만으로 모든 데이터 주소에 언제나 유효한 검사 정보가 있다고 보장되지는 않아요.', 'KMSAN_META_SHADOW는 false, KMSAN_META_ORIGIN은 true예요. 이 참·거짓은 어떤 종류의 검사 정보를 찾을지 고르는 표식이에요. true가 데이터 준비 완료라는 뜻도, false가 데이터 오류라는 뜻도 아니에요. 선택값의 역할과 검사 결과를 구별하세요.'], [('이 원본의 KMSAN_ORIGIN_SIZE는 얼마인가요?', ['1바이트예요', '4바이트예요'], '정답은 두 번째예요. 원인 정보를 다루는 단위는4바이트예요. 데이터의 각 바이트를 따라가는 shadow와 원인 기록의 단위를 구별해야 해요.'), ('origin 쪽 검사 정보를 고르는 KMSAN_META_ORIGIN의 값은 무엇인가요?', ['true예요', 'false예요'], '정답은 첫 번째예요. 이 true는 origin 종류를 고르는 표식이에요. 해당 데이터가 이미 준비됐다는 검사 결과를 뜻하지는 않아요.')]), 'os1714': ('개인 작업 공책과 긴급 업무용 공책을 따로 두어요. 지금 하는 일이 어느 쪽인지 보고 맞는 공책을 고르면 서로의 기록을 덮어쓰는 일을 줄일 수 있어요.', '현재 실행 상황에 따라 task와 CPU별 검사 상태를 선택하는 원리를 이해합니다.', 'in_task 참 → 현재 작업 상태, 거짓 → 현재 CPU 상태로 두 화살표를 그리세요.', ['문맥은 지금 실행 상황에 필요한 상태의 묶음이에요. KMSAN 문맥에는 인자·반환의 검사 정보를 전달하는 공간과 검사 코드 안에 들어와 있는지 나타내는 상태 등이 들어 있어요. kmsan_get_context는 지금 사용할 문맥의 주소를 골라요.', 'in_task()는 현재가 작업 문맥인지 판단해요. 참이면 &current->kmsan_ctx를 골라요. current는 지금 실행 중인 작업이고 &는 그 작업의 KMSAN 상태가 놓인 주소를 구하는 기호예요.', 'in_task()가 거짓이면 raw_cpu_ptr(&kmsan_percpu_ctx)를 골라요. per-CPU는 CPU마다 따로 둔다는 뜻이에요. 지금 CPU에 해당하는 검사 상태를 쓰는 경로이고 일반 작업의 상태를 그대로 고르는 경로와 달라요.', '왜 나눌까요? 인터럽트는 원래 하던 작업 중에 끼어들어 사건을 처리할 수 있어요. 이때 원래 작업이 쓰던 검사 정보 전달 공간을 그대로 이용하면 그 상태와 섞일 수 있어요. core.c 주석은 인터럽트에서 쓸 CPU별 문맥을 따로 설명해요.', 'C의 조건 ? A : B는 조건이 참이면 A, 거짓이면 B를 선택하는 식이에요. 이 함수에서는 두 문맥을 합치는 것이 아니라 지금 조건에 맞는 한 주소를 돌려줘요. 반환한 포인터와 실제로 그 상태를 바꾸는 작업도 구별하세요.', '이 함수는 현재 상황에 맞는 상태를 고를 뿐 인터럽트를 새로 발생시키거나 CPU 이동을 막는 기능까지 수행하지 않아요. 주소를 선택하는 일과 실행 상황을 제어하는 일은 달라요. 실제 CPU 이동·중첩 처리 조건은 주변 호출 경로에서 확인해야 해요.'], [('in_task()가 거짓이면 어느 검사 문맥을 고르나요?', ['항상 현재 작업의 문맥이에요', '현재 CPU의 per-CPU 문맥이에요'], '정답은 두 번째예요. 조건식의 거짓 쪽은 raw_cpu_ptr(&kmsan_percpu_ctx)예요. 참일 때 고르는 current->kmsan_ctx와 구별하세요.'), ('kmsan_get_context를 부르면 인터럽트가 새로 발생하나요?', ['아니요. 지금 실행 상황에 맞는 상태 주소를 고르는 함수예요', '네. 인터럽트를 강제로 실행해요'], '정답은 첫 번째예요. 현재 조건을 읽어 둘 중 하나를 선택해요. 선택 함수에 실제 인터럽트를 발생시키는 명령은 없어요.')]), 'os1715': ('검사표를 고치는 일까지 계속 새 검사 대상으로 삼으면 검사하는 사람이 자기 일을 끝없이 다시 검사할 수 있어요. 이미 검사 중인 상황을 알아보고 다시 들어가는 것을 피해야 해요.', '재귀 진입을 피하는 조건과 중첩 인터럽트의 별도 조건을 이해합니다.', '일반작업·IRQ깊이1·IRQ깊이2·NMI를 적고 guard가0일 때 결과가 거짓·거짓·참·참인지 따라가세요.', ['runtime은 실행 중 검사 기능을 수행하는 코드예요. hook은 정해진 위치에서 검사 도구를 연결하는 진입점이에요. 검사 코드가 다른 계측 코드를 부르고 그 코드가 다시 검사 도구를 부르면 자기 자신으로 돌아오는 재귀 진입이 생길 수 있어요.', 'kmsan_in_runtime은 단순히 변수 하나만 읽지 않아요. 먼저 hardirq_count에서 IRQ 중첩 깊이를 꺼내1보다 큰지 봐요. hard IRQ는 하드웨어 인터럽트 처리와 관련돼요. 깊이2는 한 인터럽트를 처리하는 중 다시 인터럽트가 겹친 상황으로 이해할 수 있어요.', '깊이가2 이상이면 guard가0이어도 true예요. 다음으로 in_nmi()가 참이면 역시 true예요. NMI는 일반적인 인터럽트 차단 방식으로 막지 못하는 특별한 인터럽트예요. 이 두 조건을 먼저 확인한 뒤에야 선택된 문맥의 kmsan_in_runtime 필드를 읽어요.', '따라서 NMI가 아니고 guard가0이면 일반 작업과 IRQ깊이1에서는 이 함수가 false예요. IRQ깊이2에서는 true예요. 반대로 앞 조건이 모두 거짓이어도 문맥의 guard가 켜져 있으면 true예요. true는 현재 경로의 재진입을 피하려는 판단이지 검사 도구 전체를 영구히 끈다는 뜻이 아니에요.', '왜 조심해서 빠질까요? 일부 검사 함수는 메모리를 할당하거나 잠금을 사용할 수 있어요. 중첩된 실행에서 같은 자원을 기다리면 진행이 막히는 문제가 생길 수 있어서 보수적으로 진입을 피하는 것이에요. 이미 검사 중인지 확인하는 표시는 이런 상황을 다루는 데 쓰여요.', '다만 빠져나가면 값이 준비되는 사건을 놓칠 수 있는 비용도 있어요. 원문은 이를 줄이려고 기다림이 없는 non-blocking runtime 함수에는 이 검사를 하지 않는다고 설명해요. 모든 검사 함수가 예외 없이 동일한 guard 검사를 한다고 일반화하지 마세요.'], [('IRQ 중첩 깊이가2이고 문맥 guard가0이면 이 함수는 참인가요?', ['아니요. guard만 읽으니 거짓이에요', '네. 먼저 중첩 IRQ 조건에서 참을 돌려줘요'], '정답은 두 번째예요. 깊이>1 검사가 문맥 필드 읽기보다 먼저예요. 따라서 guard0만 보고 최종 결과를 정하면 틀려요.'), ('원문은 모든 non-blocking runtime 함수도 반드시 이 검사를 한다고 하나요?', ['아니요. 초기화 사건을 놓치는 일을 줄이려 검사를 하지 않는 경우를 설명해요', '네. 어떤 함수에도 예외가 없어요'], '정답은 첫 번째예요. 재진입을 피하는 이점과 초기화 추적을 놓치는 비용을 함께 고려해요. 함수의 성질에 따라 별도 처리가 있음을 읽어야 해요.')]), 'os1716': ('방에 들어갈 때 표시를0에서1로 바꾸고 나올 때1에서0으로 돌려요. 이미1인데 또 들어가거나 들어오지 않았는데 나오면 순서가 맞지 않는 것이에요.', '후위 증가와 전위 감소가 검사하는 값과 저장하는 값을 구별합니다.', '정상 진입의 검사값0·저장값1, 정상 종료의 검사값0·저장값0을 두 열로 적으세요.', ['kmsan_enter_runtime은 검사 runtime에 들어갈 때, kmsan_leave_runtime은 나올 때 쓰는 도우미예요. 둘 다 현재 상황에 맞는 문맥을 골라 kmsan_in_runtime 숫자를 바꿔요. 정상적인 한 번의 진입과 종료는0→1→0이에요.', 'enter의 식은 KMSAN_WARN_ON(ctx->kmsan_in_runtime++)예요. x++는 저장된 x를1 늘리지만 식의 값으로는 늘리기 전 값을 사용해요. x가0이면 경고 조건이 보는 값은0이고 저장 상태는1이 돼요. 그래서 첫 정상 진입에서는 이 조건이 경고를 요구하지 않아요.', '이미1인데 다시 enter하면 이전 값1이 경고 조건에 들어가고 저장 상태는2가 돼요. 경고를 검사한다는 이름만 보고 값은 그대로라고 생각하면 안 돼요. 이 식에는 상태를 바꾸는 효과도 들어 있어요.', 'leave의 식은 KMSAN_WARN_ON(--ctx->kmsan_in_runtime)이에요. --x는 먼저1을 줄이고 줄어든 값을 식의 결과로 써요. 정상 상태1에서 나가면 저장값과 경고 조건값이 모두0이에요. 이 차이를 알면 ++가 뒤에 있는지 --가 앞에 있는지 읽을 이유가 생겨요.', '숫자 연습으로 진입 두 번 뒤 종료 두 번을 계속 계산하면 저장 상태는0→1→2→1→0이고 경고 조건값은0·1·1·0이에요. 이것은 식을 따라가는 연습이에요. 실제 경고가 발생했을 때 계속 실행되는지는 오류 처리 설정에 달려 있으므로 모든 실제 실행이 끝까지 간다고 보장하지 않아요.', '경고는 잘못된 사용을 알려 주는 것이지 값을 자동으로 정상 상태로 되돌리는 기능이 아니에요. 진입과 종료는 맞는 흐름으로 짝지어야 해요. 정상 leave 뒤0으로 돌아와야 다음 진입에서 이전 검사가 아직 진행 중이라고 잘못 판단하지 않아요.'], [('enter의 x++에서 경고 조건이 받는 값은 어느 것인가요?', ['언제나 증가한 뒤의 값이에요', '증가하기 전의 값이에요'], '정답은 두 번째예요. 후위 증가는 식의 결과로 이전 값을 주면서 저장값은1 늘려요. 처음0이면 조건값0·저장값1이므로 두 값을 구별해야 해요.'), ('정상적으로 한 번 들어왔다가 leave한 뒤 상태는 얼마인가요?', ['0이에요', '언제나1을 유지해요'], '정답은 첫 번째예요. 진입으로1이 된 값을 leave의 --가0으로 줄이고 그0을 검사해요. 정상 흐름은0→1→0으로 짝이 맞아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_424.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
